// Generated from the d3-celestial data (BSD 3-clause, Olaf Frohn): stars,
// constellation lines, names and Messier objects. Positions are for J2000.
// Do not edit by hand.

/// A star: right ascension and declination in degrees (J2000), apparent
/// magnitude and, for the brightest, its proper name.
class StarData {
  const StarData(this.ra, this.dec, this.mag, [this.name = '']);

  final double ra;
  final double dec;
  final double mag;
  final String name;
}

/// A constellation: IAU code, Latin name, names in some languages, the
/// centre of its figure and its stick figure as flat lists of
/// ra, dec, ra, dec ... (one list per connected line).
class ConstellationData {
  const ConstellationData(
      this.id, this.latin, this.names, this.ra, this.dec, this.lines);

  final String id;
  final String latin;

  /// Names by language code. Missing languages use [latin].
  final Map<String, String> names;
  final double ra;
  final double dec;
  final List<List<double>> lines;

  String nameFor(String languageCode) => names[languageCode] ?? latin;
}

/// A deep-sky object for the binocular guide.
class DeepSkyData {
  const DeepSkyData(
      this.id, this.name, this.kind, this.mag, this.ra, this.dec, this.constellation);

  /// 'M45' and so on.
  final String id;
  final String name;

  /// 0 star cluster, 1 galaxy, 2 nebula.
  final int kind;
  final double mag;
  final double ra;
  final double dec;

  /// IAU code of the constellation it lies in.
  final String constellation;
}

